test('REQ-2-1-4#3: REQ-2-1-4 -the requested workflow,the requested workflow', async ({ page }) => {
  const workbookName = 'WB ' + u();
  await createWorkbook(page, workbookName);
  await addWorksheet(page);
  await seedSourceData(page);
  await createPivot(page);

  await page.getByRole('tab', { name: 'Sheet1', exact: true }).click();
  await openWorksheetOptions(page, 'Sheet1');
  await page.getByRole('menuitem', { name: 'Delete', exact: true }).click();

  const dialog = page.getByRole('dialog', { name: 'Delete worksheet', exact: true });
  await expect(dialog).toBeVisible();
  await dialog.getByRole('button', { name: 'Delete worksheet', exact: true }).click();

  await expect(dialog).not.toBeVisible();
  await expect(
    page.getByText('Please delete or rebuild dependent pivot tables first', { exact: true })
  ).toBeVisible();

  await page.getByRole('tab', { name: 'Sheet1', exact: true }).click();
  await expect(page.getByRole('gridcell', { name: 'A1', exact: true })).toHaveText('Region');

  await page.getByRole('tab', { name: 'Pivot1', exact: true }).click();
  await expect(page.getByRole('gridcell', { name: 'B1', exact: true })).toHaveText('SUM of Sales');
  await expect(page.getByRole('gridcell', { name: 'B5', exact: true })).toHaveText('2700');

  await page.reload();
  await page.getByRole('tab', { name: 'Pivot1', exact: true }).click();
  await expect(page.getByRole('gridcell', { name: 'B5', exact: true })).toHaveText('2700');
  await expect(page.getByRole('tab', { name: 'Sheet1', exact: true })).toBeVisible();
});

test('REQ-2-2-1#2: REQ-2-2-1 -the requested workflow 3 the requested workflow,the requested workflow', async ({ page }) => {
  const name = `rw${u()}`;
  await importWorkbook(page, 'Region,Sales\nEast,1200\nNorth,800\n', name);

  await insertRowBelow(page, 2);

  await expectCellText(page, 'A1', 'East');
  await expectCellText(page, 'B1', '1200');
  await expectCellText(page, 'A2', 'North');
  await expectCellText(page, 'B2', '800');
  await expectCellText(page, 'A3', '');
  await expectCellText(page, 'B3', '');

  await page.reload();
  await expect(page.getByRole('grid', { name: 'Worksheet grid', exact: true })).toBeVisible();
  await expectCellText(page, 'A1', 'East');
  await expectCellText(page, 'B1', '1200');
  await expectCellText(page, 'A2', 'North');
  await expectCellText(page, 'B2', '800');
  await expectCellText(page, 'A3', '');
  await expectCellText(page, 'B3', '');
});

test('REQ-2-2-1#5: REQ-2-2-1 -the requested workflow', async ({ page }) => {
  const name = `pv${u()}`;
  await importWorkbook(page, 'Region,Sales\nEast,1200\nNorth,800\n', name);

  await selectRangeByDrag(page, 'A1', 'B3');
  await dataMenuItem(page, 'Create pivot table');

  const dialog = page.getByRole('dialog', { name: 'Create pivot table', exact: true });
  await expect(dialog.getByText('Source range: A1:B3', { exact: true })).toBeVisible();
  await dialog.getByRole('radio', { name: 'New worksheet', exact: true }).check();
  await dialog.getByRole('button', { name: 'Create', exact: true }).click();

  await expect(page.getByRole('tab', { name: 'Pivot1', exact: true })).toBeVisible();

  const editor = page.getByRole('region', { name: 'Pivot table editor', exact: true });
  await editor.getByLabel('Rows', { exact: true }).click();
  await page.getByRole('option', { name: 'Region', exact: true }).click();
  await editor.getByLabel('Values', { exact: true }).click();
  await page.getByRole('option', { name: 'Sales', exact: true }).click();
  await editor.getByLabel('Summarize by', { exact: true }).click();
  await page.getByRole('option', { name: 'SUM', exact: true }).click();
  await editor.getByRole('button', { name: 'Apply', exact: true }).click();

  await expectCellText(page, 'A1', 'Region');
  await expectCellText(page, 'B1', 'SUM of Sales');
  await expectCellText(page, 'B4', '2000');

  await page.getByRole('tab', { name: 'Sheet1', exact: true }).click();
  await deleteRow(page, 3);
  await page.getByRole('tab', { name: 'Pivot1', exact: true }).click();

  await expectCellText(page, 'B4', '2000');

  await page.getByRole('button', { name: 'Refresh pivot table', exact: true }).click();
  await expectCellText(page, 'A3', 'Grand Total');
  await expectCellText(page, 'B3', '1200');

  await page.reload();
  await expect(page.getByRole('grid', { name: 'Worksheet grid', exact: true })).toBeVisible();
  await expectCellText(page, 'A3', 'Grand Total');
  await expectCellText(page, 'B3', '1200');
});

// Added by the suite runner: a helper that uses `page` without taking it as a parameter sees the running test's page.
require('@playwright/test').test.beforeEach(async ({ page }) => { globalThis.page = page; });

test('REQ-2-2-2#4: REQ-2-2-2 -the requested workflow', async () => {
  await importWorkbook('Region,Sales\nEast,50\nNorth,80');

  await selectRange('B2', 'B3');
  await openDataMenu();
  await page.getByRole('menuitem', { name: 'Data validation', exact: true }).click();
  const validationDialog = page.getByRole('dialog', { name: 'Data validation', exact: true });
  await selectCombo('Rule type', 'Number range');
  await validationDialog.getByLabel('Minimum', { exact: true }).fill('0');
  await validationDialog.getByLabel('Maximum', { exact: true }).fill('100');
  await validationDialog.getByRole('button', { name: 'Save', exact: true }).click();
  await expect(validationDialog).not.toBeVisible();

  await selectRange('A1', 'B3');
  await openDataMenu();
  await page.getByRole('menuitem', { name: 'Create filter', exact: true }).click();
  await page.getByRole('button', { name: 'Filter Region', exact: true }).click();
  const filterDialog = page.getByRole('dialog', { name: 'Filter Region', exact: true });
  await filterDialog.getByRole('button', { name: 'Clear selection', exact: true }).click();
  await filterDialog.getByRole('checkbox', { name: 'East', exact: true }).check();
  await filterDialog.getByRole('button', { name: 'Apply', exact: true }).click();
  await expect(page.getByRole('gridcell', { name: 'B3', exact: true })).toBeHidden();

  await insertColumnLeft('A');

  await expect(page.getByRole('gridcell', { name: 'B2', exact: true })).toBeVisible();
  await expect(page.getByRole('gridcell', { name: 'B3', exact: true })).toBeHidden();

  await page.getByRole('gridcell', { name: 'C2', exact: true }).click();
  await page.keyboard.type('200');
  await page.keyboard.press('Enter');
  await expect(page.getByText('Please enter a number from 0 to 100', { exact: true })).toBeVisible();
  await expect(page.getByRole('gridcell', { name: 'C2', exact: true })).toHaveText('50');

  await page.reload();
  await expect(page.getByRole('grid', { name: 'Worksheet grid', exact: true })).toBeVisible();
  await expect(page.getByRole('gridcell', { name: 'C2', exact: true })).toHaveText('50');
  await expect(page.getByRole('gridcell', { name: 'B3', exact: true })).toBeHidden();
});

test('REQ-3-1-2: REQ-3-1-2 -the requested workflow B2 the requested workflow,the requested workflow', async ({ page }) => {
  await createWorkbook(page, `PasteCtx${u()}`);

  await setCell(page, 'B2', '4');
  await setCell(page, 'C2', '=B2*2');
  await setCell(page, 'C4', '=C2+C3');
  await setCell(page, 'D2', 'keep');

  await pasteViaContextMenu(page, 'B2', 'East\t1200\nNorth\t800');

  await expect(cell(page, 'B2')).toHaveText('East');
  await expect(cell(page, 'C2')).toHaveText('1200');
  await expect(cell(page, 'B3')).toHaveText('North');
  await expect(cell(page, 'C3')).toHaveText('800');
  await expect(cell(page, 'D2')).toHaveText('keep');
  await expect(cell(page, 'C4')).toHaveText('2000');

  await cell(page, 'C2').click();
  await expect(formulaBar(page)).toHaveValue('1200');
  await cell(page, 'C4').click();
  await expect(formulaBar(page)).toHaveValue('=C2+C3');

  await page.reload();
  await expect(grid(page)).toBeVisible();
  await expect(cell(page, 'B2')).toHaveText('East');
  await expect(cell(page, 'C2')).toHaveText('1200');
  await expect(cell(page, 'B3')).toHaveText('North');
  await expect(cell(page, 'C3')).toHaveText('800');
  await expect(cell(page, 'C4')).toHaveText('2000');
});

